export const routes: Record<string, DemoMeta> = {};
// zh/en names — generated by scripts/i18n/apply.py (re-run after expand_demos.py)
type Ov = { cats: Record<string, Partial<Category>>; demos: Record<string, Partial<DemoMeta>> };
const ov = i18nOverlay as unknown as Ov;
for (const c of categories) {
  Object.assign(c, ov.cats[c.key] || {});
  for (const d of c.demos) {
    d.path = `/${c.key}/${d.slug}`;
    Object.assign(d, ov.demos[d.path] || {});
    d.cat = c;
    routes[d.path] = d;
  }
}
export const totalDemos = categories.reduce((n, c) => n + c.demos.length, 0);
